/// The window's player's inventory as a native mod reads it (Arsenal's patch).
#[allow(dead_code)]
#[derive(Clone, Debug)]
pub(crate) struct NativeInventory {
    /// The 36 slots: the hotbar (0..9), then the rest.
    pub(crate) slots: Vec<Option<ItemStack>>,
    /// Head, chest, legs, feet.
    pub(crate) armor: Vec<Option<ItemStack>>,
    pub(crate) offhand: Option<ItemStack>,
    /// The hotbar slot in the main hand (0..9).
    pub(crate) selected: usize,
}

/// The window's player's inventory, for client mods (Arsenal's patch): none on the title screen.
pub(super) fn arsenal_inventory(&self) -> Option<NativeInventory> {
    self.player.as_ref()?;
    Some(NativeInventory {
        slots: self.inventory.clone(),
        armor: self.armor.iter().cloned().collect(),
        offhand: self.offhand.clone(),
        selected: self.selected,
    })
}
